-- Segmentos (exemplos de aplicação em /sistemas-personalizados): de nichos (advocacia, barbearias...)
-- para áreas amplas de negócio. Somente TEXTOS; mesmo formato (nome, ícone e itens), continua editável no /admin.
-- A troca só acontece se a lista ainda for exatamente a original; se já foi editada no /admin, nada muda.
-- Num banco novo os segmentos vêm de server/data/defaults.js.
UPDATE settings SET value = REPLACE(value, '[{"name":"Comércio e lojas","icon":"store","items":["Estoque","Produtos","Vendas","Clientes","Relatórios"]},{"name":"Restaurantes","icon":"utensils","items":["Cardápio digital","Pedidos","QR Code","Produtos","Vendas"]},{"name":"Advocacia","icon":"scale","items":["Clientes","Processos","Prazos","Documentos","Dashboard"]},{"name":"Recursos Humanos","icon":"users","items":["Funcionários","Documentos","Férias","Departamentos","Indicadores"]},{"name":"Barbearias e salões","icon":"scissors","items":["Agendamento","Clientes","Serviços","Profissionais","Histórico"]},{"name":"Empresas","icon":"building","items":["Dashboards","Indicadores","Financeiro","Operacional","Relatórios"]}]', '[{"name":"Comércio e varejo","icon":"store","items":["Estoque","Produtos","Vendas","Clientes","Relatórios"]},{"name":"Prestadores de serviço","icon":"calendar","items":["Agendamento","Ordens de serviço","Clientes","Profissionais","Histórico"]},{"name":"Alimentação e delivery","icon":"utensils","items":["Cardápio digital","Pedidos","QR Code","Entregas","Vendas"]},{"name":"Escritórios e consultorias","icon":"building","items":["Clientes","Contratos","Prazos","Documentos","Atendimentos"]},{"name":"Indústria e operação","icon":"boxes","items":["Produção","Estoque","Compras","Fornecedores","Indicadores"]},{"name":"Gestão e equipes","icon":"chart","items":["Financeiro","Funcionários","Departamentos","Dashboards","Relatórios"]}]') WHERE name = 'segments';
